
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from pathlib import Path

# Project paths
base = Path(__file__).resolve().parent.parent
data_file = base / "results" / "convergence.csv"
output_file = base / "figures" / "grid_convergence.png"

# Read results generated by Fortran
df = pd.read_csv(data_file)

h = df["dx"].to_numpy()
rmse = df["rmse"].to_numpy()
max_error = df["max_error"].to_numpy()

# Fit log(error) = p*log(h) + constant
p_rmse = np.polyfit(np.log(h), np.log(rmse), 1)[0]
p_max = np.polyfit(np.log(h), np.log(max_error), 1)[0]

# Reference second-order slope
reference = rmse[0] * (h / h[0])**2

fig, ax = plt.subplots(figsize=(7.5, 5.5))

ax.loglog(
    h, rmse, "o-",
    linewidth=2, markersize=8,
    label=f"RMSE (fitted order = {p_rmse:.3f})"
)

ax.loglog(
    h, max_error, "s-",
    linewidth=2, markersize=7,
    label=f"Maximum error (order = {p_max:.3f})"
)

ax.loglog(
    h, reference, "k--",
    linewidth=1.5,
    label="Reference: second-order slope"
)

ax.set_xlabel("Grid spacing, h (m)")
ax.set_ylabel("Absolute temperature error (°C)")
ax.set_title("Grid Convergence of the 2D Heat-Diffusion Solver")

ax.grid(True, which="both", linestyle=":", alpha=0.5)
ax.legend(fontsize=9)

fig.tight_layout()
fig.savefig(output_file, dpi=300, bbox_inches="tight")

print("Fitted RMSE convergence order:", p_rmse)
print("Fitted maximum-error order:", p_max)
print("Figure saved to:", output_file)

plt.show()

